"""Legacy dotfile DTO conversion and auto-generated file processor calls for any owner."""

from ai.backend.common.data.entity.types import EntityIdentifier
from ai.backend.common.data.filter_specs import StringMatchSpec
from ai.backend.common.dotfile import DotfilePath
from ai.backend.common.dto.manager.config.response import (
    DeleteDotfileResponse,
    DotfileListItem,
    GetDotfileResponse,
)
from ai.backend.manager.data.auto_generated_file.types import (
    AutoGeneratedFileData,
    AutoGeneratedFileRevisionSpec,
)
from ai.backend.manager.data.dotfile.types import DotfileEntry
from ai.backend.manager.dto.auto_generated_file_input import (
    CreateAutoGeneratedFileInput,
    DeleteDefaultAutoGeneratedFileInput,
    UpdateDefaultAutoGeneratedFileInput,
)
from ai.backend.manager.errors.storage import DotfileNotFound
from ai.backend.manager.models.auto_generated_file.creators import AutoGeneratedFileCreator
from ai.backend.manager.models.auto_generated_file.scopes import AutoGeneratedFileTarget
from ai.backend.manager.models.auto_generated_file.searchable_fields import (
    AutoGeneratedFileSearchableFields,
)
from ai.backend.manager.models.auto_generated_file.searchers import AutoGeneratedFileSearcher
from ai.backend.manager.models.specs.pagination import NoPagination
from ai.backend.manager.services.auto_generated_file.actions.create_default import (
    CreateDefaultAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.get_current_revisions import (
    GetCurrentAutoGeneratedFileRevisionsAction,
)
from ai.backend.manager.services.auto_generated_file.actions.purge_default import (
    PurgeDefaultAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.search import (
    SearchAutoGeneratedFilesAction,
)
from ai.backend.manager.services.auto_generated_file.actions.update import (
    UpdateAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.processors import AutoGeneratedFileProcessors


class AutoGeneratedFileAdapter:
    _auto_generated_file: AutoGeneratedFileProcessors

    def __init__(self, auto_generated_file: AutoGeneratedFileProcessors) -> None:
        self._auto_generated_file = auto_generated_file

    async def _search_default_auto_generated_files(
        self, owner: EntityIdentifier, path: str | None = None
    ) -> list[AutoGeneratedFileData]:
        fields = AutoGeneratedFileSearchableFields.own
        conditions = [fields.is_default.filter.equals(True)]
        if path is not None:
            conditions.append(
                fields.path.filter.equals(
                    StringMatchSpec(value=path, case_insensitive=False, negated=False)
                )
            )
        result = await self._auto_generated_file.search.run(
            SearchAutoGeneratedFilesAction(
                targets=[AutoGeneratedFileTarget.of_owner(owner)],
                searcher=AutoGeneratedFileSearcher(
                    pagination=NoPagination(),
                    conditions=conditions,
                    orders=[fields.created_at.order.apply(True), fields.id.order.apply(True)],
                ),
            )
        )
        return result.items

    async def _default_auto_generated_file_entries(
        self, owner: EntityIdentifier, path: str | None = None
    ) -> list[DotfileEntry]:
        """The owner's default files with their current content, read off the latest revisions."""
        auto_generated_files = await self._search_default_auto_generated_files(owner, path)
        if not auto_generated_files:
            return []
        revisions = await self._auto_generated_file.get_current_revisions.run(
            GetCurrentAutoGeneratedFileRevisionsAction(
                auto_generated_file_ids=[file.id for file in auto_generated_files]
            )
        )
        return [
            DotfileEntry(path=file.path, perm=file.perm, data=revisions.designated[file.id].data)
            for file in auto_generated_files
        ]

    async def create_default_auto_generated_file(
        self, input: CreateAutoGeneratedFileInput
    ) -> GetDotfileResponse:
        result = await self._auto_generated_file.create_default.run(
            CreateDefaultAutoGeneratedFileAction(
                creator=AutoGeneratedFileCreator(
                    owner=input.owner,
                    entry=DotfileEntry(path=input.path, perm=input.perm, data=input.data),
                ),
                creator_id=input.creator_id,
            )
        )
        return GetDotfileResponse(path=result.data.path, perm=result.data.perm, data=input.data)

    async def get_default_auto_generated_file_by_path(
        self, owner: EntityIdentifier, path: str
    ) -> GetDotfileResponse:
        entries = await self._default_auto_generated_file_entries(owner, path)
        if not entries:
            raise DotfileNotFound
        entry = entries[0]
        return GetDotfileResponse(path=entry.path, perm=entry.perm, data=entry.data)

    async def list_default_auto_generated_files(
        self, owner: EntityIdentifier
    ) -> list[DotfileListItem]:
        entries = await self._default_auto_generated_file_entries(owner)
        return [DotfileListItem(path=e.path, permission=e.perm, data=e.data) for e in entries]

    async def update_default_auto_generated_file(
        self, input: UpdateDefaultAutoGeneratedFileInput
    ) -> GetDotfileResponse:
        DotfilePath(input.path)
        auto_generated_files = await self._search_default_auto_generated_files(
            input.owner, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        result = await self._auto_generated_file.update.run(
            UpdateAutoGeneratedFileAction(
                auto_generated_file_id=auto_generated_files[0].id,
                perm=input.perm,
                revision=AutoGeneratedFileRevisionSpec(
                    data=input.data, creator_id=input.creator_id
                ),
            )
        )
        return GetDotfileResponse(path=result.data.path, perm=result.data.perm, data=input.data)

    async def purge_default_auto_generated_file(
        self, input: DeleteDefaultAutoGeneratedFileInput
    ) -> DeleteDotfileResponse:
        auto_generated_files = await self._search_default_auto_generated_files(
            input.owner, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        await self._auto_generated_file.purge_default.run(
            PurgeDefaultAutoGeneratedFileAction(auto_generated_file_id=auto_generated_files[0].id)
        )
        return DeleteDotfileResponse(success=True)
